function __lhWrap([string]$__t, [object[]]$__a) { $ErrorActionPreference = 'Continue'; $__real = (Get-Command -Name $__t -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1).Source; if (-not $__real) { throw "${__t}: command not found" }; $__dir = '__LOGDIR__'; $__id = [guid]::NewGuid().ToString(); $__enc = New-Object System.Text.UTF8Encoding $false; [void][IO.Directory]::CreateDirectory("$__dir\out"); $__start = Get-Date; $__rec = @{ phase = 'start'; callId = $__id; ts = $__start.ToUniversalTime().ToString('o'); tool = $__t; args = @($__a | ForEach-Object { "$_" }); real = $__real; cwd = (Get-Location).Path; session_id = $env:CLAUDE_CODE_SESSION_ID; platform = 'win32'; shell = 'powershell' }; [IO.File]::AppendAllText("$__dir\tool-calls.jsonl", ($__rec | ConvertTo-Json -Compress) + "`n", $__enc); $__all = & $__real @__a 2>&1; $__code = $LASTEXITCODE; $__out = New-Object System.Text.StringBuilder; $__err = New-Object System.Text.StringBuilder; foreach ($__l in $__all) { if ($__l -is [System.Management.Automation.ErrorRecord]) { [void]$__err.AppendLine($__l.ToString()) } else { [void]$__out.AppendLine("$__l") } }; [IO.File]::AppendAllText("$__dir\out\$__id.out", $__out.ToString(), $__enc); if ($__err.Length) { [IO.File]::AppendAllText("$__dir\out\$__id.err", $__err.ToString(), $__enc) }; $__end = @{ phase = 'exit'; callId = $__id; exit_code = $__code; duration_ms = [int]((Get-Date) - $__start).TotalMilliseconds; stdout_bytes = $__out.Length; stderr_bytes = $__err.Length }; [IO.File]::AppendAllText("$__dir\tool-calls.jsonl", ($__end | ConvertTo-Json -Compress) + "`n", $__enc); foreach ($__l in $__all) { if ($__l -is [System.Management.Automation.ErrorRecord]) { [Console]::Error.WriteLine($__l.ToString()) } else { $__l } }; $global:LASTEXITCODE = $__code }
